class Solution {
public:
    int numberOfArithmeticSlices(vector<int>& nums) {
        long long ans=0;
        int n=nums.size();
        vector<unordered_map<long long,long long>> mp(n);
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<i;j++)
            {
                long long diff=(long long)nums[i]-(long long)nums[j];
                if(diff<=INT_MIN || diff>=INT_MAX)
                {
                    continue;
                }
                long long seq=0;
                if(mp[j].find(diff)!=mp[j].end())
                {
                    seq=mp[j][diff];
                }
                mp[i][diff]+=seq+1;
                ans+=seq;
            }
        }
        return (int)ans;
    }
};

#define LL long long
class Solution {
public:
    int n;
    int ans;
    void dfs(int dep, vector<int>& A, vector<LL> cur) {
        if (dep == n) {
            if (cur.size() < 3) {
                return;
            }
            for (int i = 1; i < cur.size(); i++) {
                if (cur[i] - cur[i - 1] != cur[1] - cur[0]) {
                    return;
                }
            }
            ans ++;
            return;
        }
        dfs(dep + 1, A, cur);
        cur.push_back(A[dep]);
        dfs(dep + 1, A, cur);
    }
    int numberOfArithmeticSlices(vector<int>& A) {
        n = A.size();
        ans = 0;
        vector<LL> cur;
        dfs(0, A, cur);
        return (int)ans;
    }
};

